-- Synthetic duties only; no new users or reinstatement of revoked grants.
INSERT INTO ppo.permission_grants(workspace_id,user_id,company_id,capability,scope_type,scope_id,site_id,valid_from,valid_to)
SELECT g.workspace_id,g.user_id,g.company_id,cap,g.scope_type,g.scope_id,g.site_id,g.valid_from,g.valid_to
FROM ppo.permission_grants g JOIN ppo.users u ON (u.workspace_id,u.id)=(g.workspace_id,g.user_id)
CROSS JOIN unnest(CASE WHEN u.subject_id='coordinator' THEN ARRAY['supply.read','supply.coordinate','supply.inspect','supply.fulfil','supply.return','supply.custody'] ELSE ARRAY['supply.read'] END) cap
WHERE u.issuer='PPO-LocalSynthetic' AND u.subject_id IN ('coordinator','observer','site-observer','second-company','finance','finance-reviewer','finance-processor','finance-reconciler','assigned-technician','second-technician')
AND g.capability='shared.read' AND u.active AND g.valid_from<=clock_timestamp() AND (g.valid_to IS NULL OR g.valid_to>clock_timestamp()) ON CONFLICT DO NOTHING;

