SELECT v.id::uuid,'10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000001',v.kind,v.reference,v.title,'SYN-PART-CABLE','EA',v.quantity::numeric,'30000000-0000-4000-8000-000000000001',v.action,v.data::jsonb,v.completeness,'2026-09-24T00:00:00Z','SYN manual coordination example; no source-system observation','Initial fictional coordination example','30000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001'
FROM (VALUES
('5c000049-0000-4000-8000-000000000001','Demand','SYN-PPO-SC-DEMAND-001','SYN Cable demand for review','10','Confirm usable allocation and inspect incoming goods','{"demand_class":"Approved","origin_kind":"OtherApproved","origin_reference":"SYN approved demonstration demand","authority":"SYN prototype authority only","required_on":"2026-10-01","timezone":"Australia/Sydney","source_revision":"SYN scope 1","customer_id":"50000000-0000-4000-8000-000000000001","technical_release":"Not established","material_release":"Not established"}','Complete'),
('5c000049-0000-4000-8000-000000000002','Supply','SYN-PPO-SC-STOCK-001','SYN Warehouse cable observation','6','Review source basis before allocating','{"supply_kind":"Stock","line_reference":"SYN-CABLE-WH1","supplier":"SYN fixture company A","warehouse":"SYN-WH-01","bin":"SYN-BIN-A","on_hand":"8","available":"6","reserved":"0","held":"2","usable":"6","availability_basis":"SYN counted usable evidence; available basis not adopted for MYOB","eta_basis":"Unknown"}','Complete'),
('5c000049-0000-4000-8000-000000000003','Supply','SYN-PPO-SC-SHIPMENT-001','SYN Split cable shipment','10','Confirm ETA and receipt inspection','{"supply_kind":"Shipment","shipment_id":"5c000049-0000-4000-8000-000000000010","line_reference":"SYN-INBOUND-L1","supplier":"SYN supplier; fictional company A","warehouse":"SYN-WH-01","availability_basis":"Incoming evidence only","eta":"2026-10-03","eta_basis":"Estimated","purchase_reference":"SYN unverified PO example"}','Partial')
